# IMPERIA COLD WAR — COMECON native ballot, catalogue and referral cases

def compile_cases(controller,a):
    ai='DDR' if controller=='HUN' else 'HUN'
    return '\n'.join([
      'set_variable = { cc_council_treasury_before = treasury } set_variable = { cc_council_quote_before = global.cc_3_cost }',
      a('check_variable = { global.year = 1970 } check_variable = { global.cc_ballot_open = 1 } check_variable = { global.cc_ballot_days_left = 15 } check_variable = { global.cc_ballot_register^num = 1 }','native_calendar_and_human_only_opening_register'),
      a('UKR = { NOT = { is_in_array = { array = global.cc_ballot_register value = THIS } } NOT = { cc_ballot_can_vote = yes } }','union_republic_has_no_separate_ballot'),
      'set_variable = { cc_ballot_proposed = THIS.id } cc_ballot_cast = yes',
      a('NOT = { check_variable = { cc_ballot_receipt = global.cc_ballot_round } }','unissued_or_stale_ballot_cannot_vote'),
      f'{ai} = {{ set_variable = {{ cc_ballot_view_round = global.cc_ballot_round }} set_variable = {{ cc_ballot_proposed = {controller}.id }} cc_ballot_cast = yes }}',
      a('check_variable = { global.cc_ballots_received = 0 }','actual_ai_cannot_lodge_ballot'),
      'set_variable = { cc_ballot_view_round = global.cc_ballot_round } set_variable = { cc_ballot_proposed = THIS.id } cc_ballot_cast = yes',
      a('check_variable = { cc_ballot_target = THIS.id } check_variable = { cc_ballot_receipt = global.cc_ballot_round } check_variable = { global.cc_ballots_received = 1 } check_variable = { cc_ballot_tally = 1 }','flag_choice_seals_one_ballot'),
      f'set_variable = {{ cc_ballot_proposed = {ai}.id }} cc_ballot_cast = yes cc_ballot_count = yes',
      a('check_variable = { cc_ballot_target = THIS.id } check_variable = { global.cc_ballots_received = 1 } check_variable = { cc_ballot_tally = 1 }','repeated_or_changed_flag_cannot_replace_sealed_vote'),
      'set_variable = { cc_test_ballot_round = global.cc_ballot_round } cc_ballot_begin = yes cc_ballot_resolve = yes',
      a('check_variable = { global.cc_ballot_round = cc_test_ballot_round } check_variable = { global.cc_ballot_open = 1 }','same_year_reopen_and_early_resolution_rejected'),
      'set_variable = { global.cc_ballot_start_day = global.num_days } subtract_from_variable = { global.cc_ballot_start_day = 14 } cc_election_tick = yes cc_election_tick = yes',
      a('check_variable = { global.cc_ballot_days_left = 1 } check_variable = { global.cc_ballot_open = 1 }','deadline_uses_elapsed_days_not_number_of_callbacks'),
      f'{ai} = {{ add_to_array = {{ global.cc_ballot_candidates = THIS }} set_variable = {{ cc_ballot_tally = 99 }} }} subtract_from_variable = {{ global.cc_ballot_start_day = 1 }} cc_election_tick = yes',
      a('check_variable = { global.cc_ballot_open = 0 } check_variable = { global.cc_chair = THIS.id } check_variable = { global.cc_ballot_winner = THIS.id }','fifteenth_day_count_excludes_ineligible_ai_candidate'),
      'cc_update_authority = yes cc_ballot_resolve = yes cc_initialize = yes',
      a('check_variable = { global.cc_chair = THIS.id } check_variable = { global.cc_ballot_round = cc_test_ballot_round } check_variable = { global.cc_3_cost = cc_council_quote_before } check_variable = { treasury = cc_council_treasury_before }','closed_result_survives_refresh_without_touching_contracts'),
      'set_variable = { global.cc_ballot_year = global.year } subtract_from_variable = { global.cc_ballot_year = 1 } cc_election_tick = yes',
      a('check_variable = { global.cc_ballot_open = 1 } check_variable = { global.cc_ballot_days_left = 15 } NOT = { check_variable = { global.cc_ballot_round = cc_test_ballot_round } }','changed_calendar_year_opens_next_register_once'),
      'set_variable = { cc_ballot_proposed = THIS.id } cc_ballot_cast = yes',
      a('check_variable = { global.cc_ballots_received = 0 }','previous_round_ballot_cannot_vote_in_new_register'),
      'set_variable = { global.cc_ballot_start_day = global.num_days } subtract_from_variable = { global.cc_ballot_start_day = 15 } cc_election_tick = yes',
      a('check_variable = { global.cc_ballot_open = 0 } check_variable = { global.cc_chair = THIS.id } check_variable = { global.cc_ballots_received = 0 }','empty_ballot_uses_eligible_order_without_fabricating_votes'),
      'set_variable = { cc_catalog_offer = 44 } set_variable = { cc_catalog_tier = 3 } set_variable = { cc_view_tab = 4 } cc_ui_refresh = yes',
      a('check_variable = { global.cc_3_offer = 16 } check_variable = { global.cc_3_cost = cc_council_quote_before } check_variable = { treasury = cc_council_treasury_before } check_variable = { cc_catalog_project = 22 }','catalogue_browsing_keeps_shared_contract_and_money_unchanged'),
      'cc_agenda_submit = yes',
      a('check_variable = { cc_agenda_pending = 1 } check_variable = { cc_agenda_offer = 44 } check_variable = { cc_agenda_tier = 3 } check_variable = { treasury = cc_council_treasury_before }','member_referral_commits_no_capital'),
      f'{ai} = {{ set_variable = {{ cc_catalog_offer = 44 }} set_variable = {{ cc_catalog_tier = 1 }} cc_agenda_submit = yes }}',
      a(f'{ai} = {{ check_variable = {{ cc_agenda_pending = 0 }} }}','passive_ai_cannot_submit_agenda_item'),
      'set_variable = { cc_view_slot = 3 } cc_3_prepare_catalogue = yes',
      a('check_variable = { global.cc_3_offer = 16 } check_variable = { global.cc_3_phase = 4 }','catalogue_cannot_overwrite_sealed_or_completed_file'),
      'set_variable = { cc_view_slot = 2 } cc_1_prepare_catalogue = yes',
      a('check_variable = { global.cc_1_offer = 1 }','catalogue_command_cannot_move_into_another_file'),
      'set_variable = { cc_view_slot = 1 } set_variable = { cc_view_tab = 3 } set_variable = { cc_agenda_selected = THIS.id } set_variable = { cc_agenda_selected_revision = -1 } cc_1_prepare_agenda = yes',
      a('check_variable = { cc_agenda_pending = 1 } check_variable = { global.cc_1_offer = 1 }','stale_referral_selection_is_rejected'),
      'set_variable = { cc_agenda_selected_revision = cc_agenda_revision } cc_1_prepare_agenda = yes',
      a('check_variable = { cc_agenda_pending = 0 } check_variable = { global.cc_1_offer = 44 } check_variable = { global.cc_1_tier = 3 } check_variable = { global.cc_1_phase = 0 } check_variable = { treasury = cc_council_treasury_before }','chair_prepares_referral_without_ratifying_or_charging'),
    ])
